// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// Fixed-camera framing for the Camera Rig, SDK-free.
//
// The camera looks at a target point along a fixed heading (yaw) and a fixed
// pitch below the horizon. fitDistance() answers "how far back must it sit so
// the whole box is on screen" exactly, by projecting the box's eight corners
// into camera space, for the canvas aspect at hand — a phone's 1600x720 canvas
// is wider than a desktop's but no taller, so the two answers differ.
//
// Heading follows the SDK's frame: +Z is forward, +X right, +Y up, and a pitch
// of θ turns the forward vector down to (0, -sin θ, cos θ).
import { mulQuat, rotateVec, type Quat, type Vec3 } from './worldTransform'

export type CameraMode = 'top-down' | 'isometric' | 'follow'

/** Vertical field of view the rig sets on its camera, in degrees — the explorer's default. */
export const CAMERA_FOV_DEG = 60
export const DESKTOP_ASPECT = 16 / 9
export const PHONE_ASPECT = 1600 / 720
// Not 90: with the camera looking exactly down, "forward" has no horizontal
// part, and an explorer that steers the avatar along the camera's flattened
// forward would have nothing to steer by.
export const TOP_DOWN_PITCH_DEG = 88
const MIN_PITCH_DEG = 10
// The phone's joystick and buttons sit over the bottom corners of the canvas.
const DESKTOP_MARGIN = 1.1
const PHONE_MARGIN = 1.25
const NEAR_M = 0.5
const MIN_DISTANCE_M = 2
/** What 'follow' frames around the player when no fitSize is set. */
export const FOLLOW_FRAME_M = 10
const AVATAR_HEIGHT_M = 2

export interface Box {
  /** along the camera's right axis */
  width: number
  /** along the camera's flattened forward */
  depth: number
  height: number
}

export interface CameraPose {
  position: Vec3
  rotation: Quat
}

const DEG = Math.PI / 180

function finitePositive(value: number, fallback: number): number {
  return Number.isFinite(value) && value > 0 ? value : fallback
}

export function pitchFor(mode: CameraMode, angleDeg: number): number {
  if (mode === 'top-down') return TOP_DOWN_PITCH_DEG
  const angle = Number.isFinite(angleDeg) ? angleDeg : 55
  return Math.min(TOP_DOWN_PITCH_DEG, Math.max(MIN_PITCH_DEG, angle))
}

/** Heading of a rotation in radians: 0 looks along +Z, π/2 along +X. Tilt and roll are ignored. */
export function yawOf(rotation: Quat): number {
  const forward = rotateVec(rotation, { x: 0, y: 0, z: 1 })
  if (Math.hypot(forward.x, forward.z) > 1e-6) return Math.atan2(forward.x, forward.z)
  // Pointing straight up or down: the rotated up vector carries the heading.
  const up = rotateVec(rotation, { x: 0, y: 1, z: 0 })
  const sign = forward.y < 0 ? 1 : -1
  return Math.hypot(up.x, up.z) > 1e-6 ? Math.atan2(sign * up.x, sign * up.z) : 0
}

export function cameraRotation(yawRad: number, pitchDeg: number): Quat {
  const yaw = { x: 0, y: Math.sin(yawRad / 2), z: 0, w: Math.cos(yawRad / 2) }
  const pitch = { x: Math.sin((pitchDeg * DEG) / 2), y: 0, z: 0, w: Math.cos((pitchDeg * DEG) / 2) }
  return mulQuat(yaw, pitch)
}

/** Canvas width over height; a missing or degenerate canvas falls back by platform. */
export function aspectFor(canvas: { width: number; height: number } | null, mobile: boolean): number {
  if (canvas !== null && canvas.width > 0 && canvas.height > 0) {
    const aspect = canvas.width / canvas.height
    if (Number.isFinite(aspect)) return aspect
  }
  return mobile ? PHONE_ASPECT : DESKTOP_ASPECT
}

export function marginFor(mobile: boolean): number {
  return mobile ? PHONE_MARGIN : DESKTOP_MARGIN
}

/**
 * Distance from the box's centre to the camera so every corner is in view, for
 * a camera at `pitchDeg` below the horizon with a vertical FOV of `fovDeg`.
 */
export function fitDistance(box: Box, pitchDeg: number, aspect: number, fovDeg = CAMERA_FOV_DEG, margin = 1): number {
  const scale = finitePositive(margin, 1)
  const halfW = (Math.abs(box.width) * scale) / 2
  const halfD = (Math.abs(box.depth) * scale) / 2
  const halfH = (Math.abs(box.height) * scale) / 2
  const tanV = Math.tan((finitePositive(fovDeg, CAMERA_FOV_DEG) * DEG) / 2)
  const tanH = tanV * finitePositive(aspect, DESKTOP_ASPECT)
  const sin = Math.sin(pitchDeg * DEG)
  const cos = Math.cos(pitchDeg * DEG)
  let distance = MIN_DISTANCE_M
  for (const a of [-halfW, halfW]) {
    for (const b of [-halfD, halfD]) {
      for (const c of [-halfH, halfH]) {
        // Corner offset from the centre, in camera space: right, up, forward.
        const x = a
        const y = b * sin + c * cos
        const z = b * cos - c * sin
        const needed = Math.max(Math.abs(x) / tanH, Math.abs(y) / tanV, NEAR_M) - z
        if (needed > distance) distance = needed
      }
    }
  }
  return distance
}

export interface FramingInput {
  mode: CameraMode
  /** The creator's distance param; 0 or less means fit. */
  distance: number
  /** The creator's fitSize param; 0 or less means the rig's own area. */
  fitSize: number
  /** The rig's world scale — its area in metres. */
  area: Vec3
  pitchDeg: number
  aspect: number
  mobile: boolean
}

export function framingDistance(input: FramingInput): number {
  if (Number.isFinite(input.distance) && input.distance > 0) return input.distance
  const fit = Number.isFinite(input.fitSize) && input.fitSize > 0 ? input.fitSize : 0
  let box: Box
  if (input.mode === 'follow') {
    const side = fit > 0 ? fit : FOLLOW_FRAME_M
    box = { width: side, depth: side, height: AVATAR_HEIGHT_M }
  } else if (fit > 0) {
    box = { width: fit, depth: fit, height: Math.abs(input.area.y) }
  } else {
    box = { width: Math.abs(input.area.x), depth: Math.abs(input.area.z), height: Math.abs(input.area.y) }
  }
  return fitDistance(box, input.pitchDeg, input.aspect, CAMERA_FOV_DEG, marginFor(input.mobile))
}

/** Where the camera sits to look at `target` from `distance` metres along the given heading and pitch. */
export function cameraPose(target: Vec3, yawRad: number, pitchDeg: number, distance: number): CameraPose {
  const rotation = cameraRotation(yawRad, pitchDeg)
  const forward = rotateVec(rotation, { x: 0, y: 0, z: 1 })
  return {
    position: {
      x: target.x - forward.x * distance,
      y: target.y - forward.y * distance,
      z: target.z - forward.z * distance
    },
    rotation
  }
}

/**
 * Which rig owns the screen when several want it: the one entered last, and the
 * one entered before it once that one lets go. `applied` is what was last
 * written to MainCamera, so a rig never clears a camera someone else set.
 */
export interface RigClaims<K> {
  order: K[]
  applied: K | null
}

export function claimCamera<K>(claims: RigClaims<K>, key: K): void {
  if (!claims.order.includes(key)) claims.order.push(key)
}

export function releaseCamera<K>(claims: RigClaims<K>, key: K): void {
  claims.order = claims.order.filter((entry) => entry !== key)
}

export function cameraOnTop<K>(claims: RigClaims<K>): K | null {
  return claims.order.length > 0 ? claims.order[claims.order.length - 1] : null
}
